use crate::{model::*,unit_support::*,wm027 as b};
#[test]fn wm027_original_closed_identity(){let c=crate::catalog::card(b::ID);assert!(!c.supported);assert!(crate::catalog::runtime_implemented(c));assert_eq!(c.cost,1);assert_eq!(c.loyalty,["蓝色","蓝色","蓝色"]);assert_eq!(c.magic,"死亡");assert_current_serial_catalog();crate::rules::validate_definitions(crate::rules::definitions()).unwrap();}
fn attach(g:&mut Game,id:&str)->String{fund(g,0,"XQ14",3);let c=held(g,id,0);act(g,0,Action{card_id:Some(c),target_id:Some("society:p0".into()),..Action::new("play")});top(g);g.attachments.last().unwrap().card.id.clone()}
fn victory(g:&mut Game,win:bool){let cards=if win{["WM025","WM025","JC125","JC125"]}else{["JC125","JC125","WM025","WM025"]};let shown=cards.iter().enumerate().map(|(s,id)|held(g,id,s)).collect::<Vec<_>>();fund(g,0,"JC125",2);let c=held(g,"BQ090",0);act(g,0,Action{card_id:Some(c),ability_id:Some(crate::import20_contest::HAND.into()),..Action::new("activate")});crate::jc029_tests::pass_top(g);for _ in 0..96{if let Some(p)=g.pending.clone(){if matches!(&p.resolution,ChoiceResolution::Declare{declaration:d,..}if d.ability.key==b::WIN){return}if p.choice.kind==crate::mystic_contest::COMMIT_KIND{choose(g,vec![shown[p.seat].clone()]);}else if p.choice.kind==crate::mystic_contest::REWARD_KIND{choose(g,vec![]);}else{resolve_choice(g);}}else if !g.stack.is_empty(){pass(g);}else{return}}panic!("real contest bounded")}
fn ready()->Game{let mut g=game();attach(&mut g,b::ID);field(&mut g,"JC031",0);victory(&mut g,true);assert!(matches!(&g.pending.as_ref().unwrap().resolution,ChoiceResolution::Declare{declaration:d,..}if d.ability.key==b::WIN));g}
fn search(g:&mut Game,seat:usize){choose(g,vec!["accept".into()]);crate::jc029_tests::pass_top(g);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"wm027_enemy_deck");choose(g,vec![player_id(seat)]);assert_eq!(g.pending.as_ref().unwrap().choice.kind,"wm027_top_ten");}
fn corrupt(g:&Game){assert!(Game::from_persisted(&serde_json::to_string(g).unwrap()).is_err());let r=crate::room::RoomEnvelope::from_game(g.clone());assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn wm027_paid_entry_one_path_both_orders_and_response_conflict(){for first in [b::ID,"XQ13","JC034"]{let mut g=game();attach(&mut g,first);fund(&mut g,0,"XQ14",3);let c=held(&mut g,if first==b::ID{"XQ13"}else{b::ID},0);reject(&mut g,0,Action{card_id:Some(c.clone()),target_id:Some("society:p0".into()),..Action::new("play")});assert!(!g.legal_actions(0).iter().any(|a|a.action.kind=="play"&&a.action.card_id.as_ref()==Some(&c)));}let mut g=game();fund(&mut g,0,"XQ14",3);let c=held(&mut g,b::ID,0);act(&mut g,0,Action{card_id:Some(c),target_id:Some("society:p0".into()),..Action::new("play")});let c=g.make_card("JC034",0);g.attachments.push(Attachment{card:c,host_id:"society:p0".into()});top(&mut g);assert!(g.players[0].graveyard.iter().any(|c|c.definition==b::ID));assert_eq!(g.attachments.len(),1);}
#[test]fn wm027_real_win_top_ten_owner_seal_private_and_shuffle(){let mut g=ready();let before=g.players[2].deck.len();let id=g.players[2].deck[0].id.clone();let definition=g.players[2].deck[0].definition.clone();g.players[2].deck[0].owner=3;search(&mut g,2);let p=g.pending.clone().unwrap();assert_eq!(p.choice.options.len(),10.min(before));for s in 1..4{assert!(g.view(s).pending_choice.is_none());}reject(&mut g,1,Action{choice_id:Some(p.choice.id.clone()),selected:Some(vec![id.clone()]),..Action::new("choose")});let beyond=g.players[2].deck[10].id.clone();reject(&mut g,0,Action{choice_id:Some(p.choice.id.clone()),selected:Some(vec![beyond]),..Action::new("choose")});choose(&mut g,vec![id.clone()]);assert_eq!(g.players[2].deck.len(),before-1);assert!(g.sealed_cards.iter().any(|s|s.card.definition==definition&&s.card.owner==3&&s.card.id!=id&&s.host_id=="society:p3"));restore(&mut g);}
#[test]fn wm027_optional_decline_and_short_empty_decks(){let mut g=ready();let deck=g.players[2].deck.clone();choose(&mut g,vec![]);assert_eq!(g.players[2].deck,deck);for n in [0,1,4]{let mut g=ready();g.players[2].deck.truncate(n);search(&mut g,2);assert_eq!(g.pending.as_ref().unwrap().choice.options.len(),n);choose(&mut g,vec![]);assert_eq!(g.players[2].deck.len(),n);restore(&mut g);}}
#[test]fn wm027_no_trigger_for_loss_teammate_only_or_missing_condition(){for mode in 0..3{let mut g=game();attach(&mut g,b::ID);if mode==0{field(&mut g,"JC031",0);}if mode==1{field(&mut g,"JC031",1);}victory(&mut g,mode!=0);assert!(!g.pending.as_ref().is_some_and(|p|matches!(&p.resolution,ChoiceResolution::Declare{declaration:d,..}if d.ability.key==b::WIN)));}}
#[test]fn wm027_secrecy_condition_rechecked_and_source_departure_preserves_trigger(){let mut g=game();let source=attach(&mut g,b::ID);g.add_society_markers(0,0,1);victory(&mut g,true);g.remove_dead(&source,RemovalCause::Destroy);search(&mut g,2);choose(&mut g,vec![]);let mut g=ready();for r in &mut g.regions{r.cards.clear();}choose(&mut g,vec!["accept".into()]);top(&mut g);assert!(g.pending.is_none());}
#[test]fn wm027_game_room_restore_rejects_wrong_deck_options_source_history_and_duplicate_event(){let mut g=ready();let mut bad=g.clone();if let ChoiceResolution::Declare{declaration:d,..}=&mut bad.pending.as_mut().unwrap().resolution{d.source.card.definition="XQ13".into();}corrupt(&bad);let mut bad=g.clone();bad.mystic_history.clear();corrupt(&bad);let mut bad=g.clone();if let ChoiceResolution::Declare{declaration:d,..}=&bad.pending.as_ref().unwrap().resolution{bad.effects.push_back(Effect::Declare{declaration:d.clone()});}corrupt(&bad);search(&mut g,2);let mut bad=g.clone();bad.pending.as_mut().unwrap().choice.options.pop();corrupt(&bad);let mut bad=g.clone();if let ChoiceResolution::Frame{choice:FrameChoice::WM027Card{seat},..}=&mut bad.pending.as_mut().unwrap().resolution{*seat=1;}corrupt(&bad);let mut bad=g.clone();bad.pending.as_mut().unwrap().seat=1;corrupt(&bad);restore(&mut g);}
fn construct(seed:u64)->Game{use crate::{catalog,deck};let mut d=deck::preset("watchers").unwrap();d.id="closed-wm027-natural".into();d.society_id=None;d.core_card_id=None;d.cards=[(b::ID,3),("WM025",1),("BQ090",3),("JC031",3),("XQ14",3),("JC029",3),("WM024",3),("XQ12",3),("XQ16",3),("JC030",3),("JZ22",3),("BQ030",3),("JC125",16)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id==b::ID).unwrap().supported=true;let d=deck::validate_with_registry(d,&cards,&catalog::catalog().societies).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("wm027-natural".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
fn pending(t:&mut crate::abi112_review_play_tests::Trace){let g=&t.room.game;let p=g.pending.clone().unwrap();if matches!(p.resolution,ChoiceResolution::Forecast{..}|ChoiceResolution::Frame{choice:FrameChoice::Forecast{..},..}){t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(p.choice.options.iter().map(|o|o.id.clone()).collect()),bottom:Some(vec![]),..Action::new("choose")});return}let selected=if matches!(&p.resolution,ChoiceResolution::Declare{declaration:d,..}if d.ability.key==b::WIN){vec!["accept".into()]}else if p.choice.kind==crate::mystic_contest::COMMIT_KIND{let id=p.choice.options.iter().max_by_key(|o|g.players[p.seat].hand.iter().find(|c|c.id==o.id).map(|c|crate::catalog::card(&c.definition).cost).unwrap_or(0)).unwrap().id.clone();vec![id]}else if p.choice.kind=="wm027_enemy_deck"{vec!["p2".into()]}else if p.choice.kind=="wm027_top_ten"{p.choice.options.first().map(|o|vec![o.id.clone()]).unwrap_or_default()}else{let mut v=p.choice.options.iter().collect::<Vec<_>>();v.sort_by_key(|o|g.players[p.seat].hand.iter().any(|c|c.id==o.id&&c.definition!="JC125"));v.into_iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()};t.choose(selected);}
fn duplicates(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);s["duplicate"]=serde_json::to_value(d).unwrap();}v}
#[test]fn wm027_natural_paid_path_personal_contest_and_seal_export(){use crate::abi112_review_play_tests::Trace;let(seed,g)=(1..2049).find_map(|seed|{let g=construct(seed);let mut p=g.clone();while p.pending.is_some(){choose(&mut p,vec![]);}let h=&p.players[0].hand;[b::ID,"JC031","BQ090"].iter().all(|id|h.iter().any(|c|&c.definition==id)).then_some((seed,g))}).unwrap();let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"wm027-natural-paid-path-win-seal".into(),927);let(mut host,mut attached,mut contest)=(false,false,false);for _ in 0..1800{if t.room.game.pending.is_some(){pending(&mut t);continue}if contest&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty()&&t.room.game.mystic_contest.is_none(){break}if !t.room.game.stack.is_empty()||t.room.pacing.window.is_some(){t.pass();continue}let g=&t.room.game;let legal=g.legal_actions(0);let blue=g.players[0].assets.iter().filter(|c|crate::catalog::card(&c.definition).color=="蓝").count();let a=if blue<3{legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&crate::catalog::card(&c.definition).color=="蓝"&&!matches!(c.definition.as_str(),"WM027"|"JC031"|"WM025"))))}else if !host{legal.iter().find(|a|a.action.kind=="deploy"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="JC031")))}else if !attached{legal.iter().find(|a|a.action.kind=="play"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==b::ID)))}else if g.players[0].hand.iter().any(|c|c.definition!="BQ090"&&crate::catalog::card(&c.definition).cost>0){legal.iter().find(|a|a.action.ability_id.as_deref()==Some(crate::import20_contest::HAND))}else{None};if let Some(a)=a{match a.action.kind.as_str(){"deploy"=>host=true,"play"=>attached=true,"activate"=>contest=true,_=>()}t.action(0,a.action.clone());}else{t.pass();}}
assert!(host&&attached&&contest,"natural stages {host}/{attached}/{contest} assets={:?} hand={:?} status={} turn={}",t.room.game.players[0].assets.iter().map(|c|&c.definition).collect::<Vec<_>>(),t.room.game.players[0].hand.iter().map(|c|&c.definition).collect::<Vec<_>>(),t.room.game.status,t.room.game.turn);assert!(t.room.game.sealed_cards.iter().any(|s|s.host_id=="society:p2"),"actual enemy deck card sealed");let mut natural=t.value();natural["construction"]=serde_json::json!({"deck":deck,"seed":seed,"privateRegistryCandidates":[b::ID],"noLayoutOrResourceMutation":true});let mut g=ready();let c=g.players[2].deck[0].definition.clone();g.players[2].deck[0].owner=3;let mut t=Trace::new_preserving_rng(g,"wm027-prepared-real-victory-owner-seal".into(),928);for _ in 0..80{if t.room.game.pending.is_some(){pending(&mut t)}else if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break}else{t.pass();}}assert!(t.room.game.sealed_cards.iter().any(|s|s.card.definition==c&&s.card.owner==3&&s.host_id=="society:p3"));let cases=vec![duplicates(natural),duplicates(t.value())];if let Ok(path)=std::env::var("WM027_NATIVE_OUT"){use sha2::{Digest,Sha256};let mut binding=crate::bq052_tests::source_bindings();for(n,s)in[("rust-game/src/wm027.rs",include_str!("wm027.rs")),("rust-game/src/wm027_tests.rs",include_str!("wm027_tests.rs"))]{binding["files"][n]=format!("{:x}",Sha256::digest(s.as_bytes())).into();}std::fs::write(path,serde_json::to_vec(&serde_json::json!({"catalog":crate::catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}
